/**
 * Zoom limits for the receipt viewer.
 *
 * 100% means fit-to-viewport, not 1:1 — so a flat maximum percentage means
 * different things on different screens. The ceiling is therefore derived from
 * the individual image: zoom stops where one image pixel fills one CSS pixel.
 * See the "Zoom never invents pixels" invariant in `docs/domain-model.md`.
 */

export interface FitDimensions {
	width: number;
	height: number;
}

/** The floor, and the meaning of "fit to viewport". */
export const MIN_ZOOM = 100;

/** Zoom in/out snap to multiples of this. */
export const ZOOM_STEP = 50;

/**
 * Where a double-tap lands. Clamped to the image's own ceiling like every other
 * zoom destination, so on a small receipt it simply stays put.
 */
export const DOUBLE_TAP_ZOOM = 200;

/**
 * The share of the window the viewer gives the receipt. This is what "100%"
 * means, so the ceiling arithmetic and the CSS that clips the container must use
 * the same numbers — the component derives both from here rather than repeating
 * `90vw` / `80vh` as literals.
 */
export const VIEWPORT_FRACTION = { width: 0.9, height: 0.8 };

/**
 * The size an image occupies at 100% zoom: scaled down to fit the viewport box,
 * never scaled up. An image smaller than the box is already at native size, so
 * 100% is also its ceiling.
 */
export function calculateFitDimensions(
	naturalWidth: number,
	naturalHeight: number,
	viewportWidth: number,
	viewportHeight: number
): FitDimensions {
	const scale = Math.min(viewportWidth / naturalWidth, viewportHeight / naturalHeight, 1);
	return { width: naturalWidth * scale, height: naturalHeight * scale };
}

/**
 * The zoom percentage at which the image is displayed at its true resolution —
 * the point past which further magnification would only interpolate.
 *
 * Returns MIN_ZOOM when the image is already at (or below) native size on
 * screen, which is what disables the zoom controls: there are no further real
 * pixels to show, and a greyed-out control says so honestly.
 */
export function calculateMaxZoom(naturalWidth: number, baseWidth: number): number {
	if (baseWidth <= 0) return MIN_ZOOM;
	return Math.max(MIN_ZOOM, (naturalWidth / baseWidth) * MIN_ZOOM);
}
=====SPEC=====
/**
 * Zoom-limit arithmetic for the receipt viewer.
 *
 * The invariant under test is "zoom never invents pixels" (see the domain model):
 * 100% means fit-to-viewport, so the ceiling is a property of the individual
 * image rather than a fixed percentage. These are the pure calculations; the
 * component test drives the resulting button states.
 */
import { describe, it, expect } from 'vitest';
import { MIN_ZOOM, calculateFitDimensions, calculateMaxZoom } from './imageZoom';

describe('calculateFitDimensions', () => {
	it('shrinks an image larger than the viewport, preserving aspect ratio', () => {
		// 4000x3000 into a 1800x1000 box — height is the binding constraint
		const fit = calculateFitDimensions(4000, 3000, 1800, 1000);

		expect(fit.height).toBeCloseTo(1000, 5);
		expect(fit.width / fit.height).toBeCloseTo(4000 / 3000, 5);
	});

	it('uses width as the constraint for a wide image', () => {
		const fit = calculateFitDimensions(4000, 1000, 1800, 1000);

		expect(fit.width).toBeCloseTo(1800, 5);
		expect(fit.height).toBeCloseTo(450, 5);
	});

	it('never enlarges an image that already fits', () => {
		const fit = calculateFitDimensions(400, 300, 1800, 1000);

		expect(fit).toEqual({ width: 400, height: 300 });
	});

	it('leaves an image exactly the size of the viewport alone', () => {
		const fit = calculateFitDimensions(1800, 1000, 1800, 1000);

		expect(fit).toEqual({ width: 1800, height: 1000 });
	});
});

describe('calculateMaxZoom', () => {
	it('is the zoom at which one image pixel fills one CSS pixel', () => {
		// Displayed at 900px wide from a 2400px source — 1:1 arrives at 266.67%
		expect(calculateMaxZoom(2400, 900)).toBeCloseTo(266.667, 2);
	});

	it('collapses to the minimum when the image is already shown at native size', () => {
		expect(calculateMaxZoom(400, 400)).toBe(MIN_ZOOM);
	});

	it('never drops below the minimum, even if the base somehow exceeds natural', () => {
		expect(calculateMaxZoom(400, 800)).toBe(MIN_ZOOM);
	});

	it('gives a full-resolution receipt more room than a resized one', () => {
		// Same display size; the pre-resize original simply has more pixels to give.
		expect(calculateMaxZoom(4000, 900)).toBeGreaterThan(calculateMaxZoom(2400, 900));
	});

	it('reports the minimum while the natural size is still unknown', () => {
		expect(calculateMaxZoom(0, 0)).toBe(MIN_ZOOM);
	});
});

1	/**
2	 * #{#rsz1a} #{#rsz1b} - Receipt Image Resizing
3	 *
4	 * Turns the **Source File** a person picked into the **Receipt Image** we store:
5	 * at most 2400px on the longest axis, JPEG at 85%, whatever arrived. The size
6	 * limits in `ReceiptService` describe the result of this function, not its
7	 * input — see `docs/adr/0006-the-stored-image-is-the-contract.md`.
8	 */
9	
10	export interface ResizeDimensions {
11		width: number;
12		height: number;
13	}
14	
15	/** Longest-axis budget for a stored Receipt Image. Chosen for human zoom, not OCR. */
16	export const MAX_IMAGE_DIMENSION = 2400;
17	
18	/** JPEG quality for a stored Receipt Image. */
19	export const IMAGE_QUALITY = 0.85;
20	
21	/** Every stored Receipt Image is a JPEG; only PDFs pass through untouched. */
22	const OUTPUT_TYPE = 'image/jpeg';
23	
24	/**
25	 * The image types a person may upload — and, necessarily, the exact set this
26	 * module can turn into a Receipt Image. "We accept it" and "we can transcode it"
27	 * have to be the same fact: `validateReceiptImage` treats anything that is not a
28	 * PDF as the JPEG this module produced, so an accepted-but-untranscodable type
29	 * would break that reasoning silently. The upload control's `accept` list is
30	 * built from this too, so adding a format is one edit.
31	 */
32	export const ACCEPTED_IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/heic'];
33	
34	/** Receipts may also be uploaded as PDFs, which are stored exactly as received. */
35	export const PDF_TYPE = 'application/pdf';
36	
37	/** Everything the receipts file input accepts. */
38	export const ACCEPTED_UPLOAD_TYPES = [...ACCEPTED_IMAGE_TYPES, PDF_TYPE];
39	
40	/**
41	 * Whether a Source File of this type should be decoded and re-encoded.
42	 *
43	 * HEIC is included deliberately: Safari — the only place HEIC originates — can
44	 * decode it into a Canvas, and skipping it sent full-resolution phone photos
45	 * straight to storage. Anything else (PDFs, and image types we never offer) is
46	 * stored exactly as received.
47	 */
48	export function isResizableImage(mimeType: string): boolean {
49		return ACCEPTED_IMAGE_TYPES.includes(mimeType);
50	}
51	
52	/**
53	 * Rename a Source File to match the JPEG we actually store, so the storage
54	 * object's extension is not a lie. This never affects `original_filename`
55	 * (#{#ofn2a}), which keeps the name the person recognizes.
56	 */
57	export function toJpegFilename(filename: string): string {
58		return filename.replace(/(\.[^./\\]*)?$/, '.jpg');
59	}
60	
61	/**
62	 * #{#rsz1a} - Calculate resize dimensions maintaining aspect ratio
63	 *
64	 * Acceptance Criteria:
65	 * - Maximum dimension on longest axis must be MAX_IMAGE_DIMENSION
66	 * - Aspect ratio must be preserved during resize
67	 * - Images already within the budget keep original dimensions
68	 *
69	 * @param originalWidth - Original image width in pixels
70	 * @param originalHeight - Original image height in pixels
71	 * @param maxSize - Maximum dimension on longest axis
72	 * @returns New dimensions with preserved aspect ratio
73	 */
74	export function calculateResizeDimensions(
75		originalWidth: number,
76		originalHeight: number,
77		maxSize: number = MAX_IMAGE_DIMENSION
78	): ResizeDimensions {
79		const longestAxis = Math.max(originalWidth, originalHeight);
80	
81		// If image is already smaller than max, keep original dimensions
82		if (longestAxis <= maxSize) {
83			return { width: originalWidth, height: originalHeight };
84		}
85	
86		// Calculate scale factor
87		const scale = maxSize / longestAxis;
88	
89		// Calculate new dimensions (preserve aspect ratio)
90		return {
91			width: Math.round(originalWidth * scale),
92			height: Math.round(originalHeight * scale)
93		};
94	}
95	
96	/** Promise-shaped `canvas.toBlob`, which is callback-only. */
97	function encodeCanvas(canvas: HTMLCanvasElement, quality: number): Promise<Blob> {
98		return new Promise((resolve, reject) => {
99			canvas.toBlob(
100				(blob) => (blob ? resolve(blob) : reject(new Error('Failed to encode image'))),
101				OUTPUT_TYPE,
102				quality
103			);
104		});
105	}
106	
107	/**
108	 * #{#rsz1a} #{#rsz1b} - Resize an image file using Canvas API
109	 *
110	 * Acceptance Criteria:
111	 * - JPEG, PNG and HEIC are all resized, and all come out as JPEG. PNG could not
112	 *   honour a quality setting while it stayed PNG — `toBlob` ignores the argument
113	 *   for lossless formats — so a PNG "resize" used to be able to grow the file.
114	 * - Resizing occurs client-side (browser) before upload
115	 * - Images already within the budget are still re-encoded, and so still shrink
116	 * - EXIF orientation is honoured (#{#rsz2b})
117	 * - The file is decoded ONCE. `createImageBitmap` is itself the decode; the
118	 *   `<img>` element this used to load first was a second full decode of the same
119	 *   bytes, doubling peak memory on exactly the large photos we now accept.
120	 *
121	 * Throws if the image cannot be decoded or encoded — the caller decides whether
122	 * that is fatal.
123	 *
124	 * @param file - Source File
125	 * @param maxSize - Maximum dimension on longest axis
126	 * @param quality - Compression quality 0-1
127	 * @returns The Receipt Image to store
128	 */
129	export async function resizeImage(
130		file: File,
131		maxSize: number = MAX_IMAGE_DIMENSION,
132		quality: number = IMAGE_QUALITY
133	): Promise<File> {
134		if (!isResizableImage(file.type)) {
135			return file;
136		}
137	
138		// #{#rsz2b} - createImageBitmap applies EXIF orientation as it decodes
139		const bitmap = await createImageBitmap(file, { imageOrientation: 'from-image' });
140	
141		try {
142			const { width, height } = calculateResizeDimensions(bitmap.width, bitmap.height, maxSize);
143	
144			const canvas = document.createElement('canvas');
145			canvas.width = width;
146			canvas.height = height;
147	
148			const ctx = canvas.getContext('2d');
149			if (!ctx) throw new Error('Canvas context not available');
150			ctx.drawImage(bitmap, 0, 0, width, height);
151	
152			// The full-resolution bitmap is dead weight the moment it has been drawn —
153			// releasing it here keeps ~48MB of RGBA for a 12MP photo from sitting
154			// alongside the canvas and the growing JPEG for the whole encode, which is
155			// the slowest step. `close()` is idempotent, so the finally below still
156			// covers every throwing path.
157			bitmap.close();
158	
159			const blob = await encodeCanvas(canvas, quality);
160	
161			return new File([blob], toJpegFilename(file.name), {
162				type: OUTPUT_TYPE,
163				lastModified: file.lastModified
164			});
165		} finally {
166			bitmap.close();
167		}
168	}
