1	<script lang="ts">
2		/**
3		 * Receipt Image Viewer Component
4		 *
5		 * Provides zoom and pan capabilities for receipt images in a floating modal.
6		 * Implements specifications #{#zom1a} through #{#zom5b} from
7		 * specs/specifications/receipt-image-zoom-pan.md
8		 *
9		 * Zoom anchors to cursor position (mouse wheel, pinch midpoint, double-tap).
10		 * Scrollable container replaces manual pan — native scrollbars + drag-to-scroll.
11		 *
12		 * @component
13		 */
14	
15		import {
16			MIN_ZOOM,
17			ZOOM_STEP,
18			DOUBLE_TAP_ZOOM,
19			VIEWPORT_FRACTION,
20			calculateFitDimensions,
21			calculateMaxZoom
22		} from '$lib/utils/imageZoom';
23	
24		// Props — #{#pdf1a} added isPdf for PDF detection
25		interface Props {
26			imageUrl: string;
27			altText?: string;
28			show?: boolean;
29			isPdf?: boolean;
30			onclose?: () => void;
31		}
32	
33		let {
34			imageUrl,
35			altText = 'Receipt image',
36			show = false,
37			isPdf = false,
38			onclose
39		}: Props = $props();
40	
41		// Zoom state - #{#zom1a}
42		let zoom = $state(100);
43	
44		// Drag-to-scroll state - #{#zom2a}
45		let isDragging = $state(false);
46		let dragStartX = $state(0);
47		let dragStartY = $state(0);
48		let scrollStartX = $state(0);
49		let scrollStartY = $state(0);
50	
51		// Touch gesture state - #{#zom3a}
52		let touchStartDistance = $state(0);
53		let touchStartZoom = $state(100);
54		let lastTapTime = $state(0);
55	
56		// Image base dimensions (fit-to-viewport at 100%)
57		let baseWidth = $state(0);
58		let baseHeight = $state(0);
59	
60		// The image's own resolution, which sets how far it can honestly be zoomed
61		let naturalWidth = $state(0);
62	
63		// Refs
64		let scrollContainer: HTMLDivElement | undefined = $state(undefined);
65	
66		// Constants
67		const PAN_STEP = 50;
68		const DOUBLE_TAP_DELAY = 300; // ms
69	
70		/**
71		 * The zoom ceiling is a property of THIS image, not a fixed percentage: it is
72		 * the point where one image pixel fills one CSS pixel. Beyond it the browser
73		 * would only interpolate, so the controls stop there — and for an image
74		 * already at or under viewport size they never leave 100% at all.
75		 */
76		let maxZoom = $derived(calculateMaxZoom(naturalWidth, baseWidth));
77	
78		/**
79		 * The box that clips the scroll container. It has to describe the same area
80		 * `handleImageLoad` fits into, since that area is what 100% means.
81		 */
82		const viewportBox = `max-width: ${VIEWPORT_FRACTION.width * 100}vw; max-height: ${VIEWPORT_FRACTION.height * 100}vh;`;
83	
84		// Pending scroll adjustment for zoom-to-cursor
85		let rafId = 0;
86	
87		// Computed scaled dimensions
88		let scaledWidth = $derived((baseWidth * zoom) / 100);
89		let scaledHeight = $derived((baseHeight * zoom) / 100);
90	
91		/**
92		 * Capture base dimensions on image load — the size the image
93		 * occupies at 100% zoom, fit within the viewport constraints.
94		 */
95		function handleImageLoad(e: Event) {
96			const img = e.target as HTMLImageElement;
97			naturalWidth = img.naturalWidth;
98			const fit = calculateFitDimensions(
99				img.naturalWidth,
100				img.naturalHeight,
101				window.innerWidth * VIEWPORT_FRACTION.width,
102				window.innerHeight * VIEWPORT_FRACTION.height
103			);
104			baseWidth = fit.width;
105			baseHeight = fit.height;
106		}
107	
108		/**
109		 * #{#zom1a} Zoom to a specific level, optionally anchored at a cursor position.
110		 * The point under the cursor stays fixed on screen after zoom.
111		 */
112		function zoomTo(newZoom: number, cursorX?: number, cursorY?: number) {
113			const container = scrollContainer;
114			newZoom = Math.max(MIN_ZOOM, Math.min(maxZoom, newZoom));
115	
116			if (!container || baseWidth === 0) {
117				zoom = newZoom;
118				return;
119			}
120	
121			const oldZoom = zoom;
122			if (newZoom === oldZoom) return;
123	
124			const rect = container.getBoundingClientRect();
125			// Default to center of viewport if no cursor position given
126			const cx = cursorX !== undefined ? cursorX - rect.left : rect.width / 2;
127			const cy = cursorY !== undefined ? cursorY - rect.top : rect.height / 2;
128	
129			// Point in base-image coordinates under the cursor
130			const imageX = (container.scrollLeft + cx) / (oldZoom / 100);
131			const imageY = (container.scrollTop + cy) / (oldZoom / 100);
132	
133			zoom = newZoom;
134	
135			// After Svelte updates the DOM (image resizes), adjust scroll so the
136			// same image point remains under the cursor.
137			const targetScrollLeft = imageX * (newZoom / 100) - cx;
138			const targetScrollTop = imageY * (newZoom / 100) - cy;
139			cancelAnimationFrame(rafId);
140			rafId = requestAnimationFrame(() => {
141				if (container) {
142					container.scrollLeft = targetScrollLeft;
143					container.scrollTop = targetScrollTop;
144				}
145			});
146		}
147	
148		/**
149		 * #{#zom1a} Zoom in by one step (snaps to 50% increments)
150		 *
151		 * The ceiling is rarely a multiple of ZOOM_STEP; `zoomTo` clamps, so the last
152		 * step lands on the ceiling itself rather than overshooting or being skipped.
153		 */
154		function zoomIn(cursorX?: number, cursorY?: number) {
155			zoomTo(Math.ceil((zoom + 1) / ZOOM_STEP) * ZOOM_STEP, cursorX, cursorY);
156		}
157	
158		/**
159		 * #{#zom1a} Zoom out by one step (snaps to 50% increments)
160		 */
161		function zoomOut(cursorX?: number, cursorY?: number) {
162			zoomTo(Math.floor((zoom - 1) / ZOOM_STEP) * ZOOM_STEP, cursorX, cursorY);
163		}
164	
165		/**
166		 * #{#zom1a} Reset zoom to 100% and scroll to origin
167		 */
168		function resetZoom() {
169			zoom = MIN_ZOOM;
170			if (scrollContainer) {
171				scrollContainer.scrollLeft = 0;
172				scrollContainer.scrollTop = 0;
173			}
174		}
175	
176		/**
177		 * #{#zom1b} #{#pdf1c} Handle mouse wheel zoom — disabled for PDFs.
178		 * Zooms toward the cursor position.
179		 */
180		function handleWheel(e: WheelEvent) {
181			if (isPdf) return; // #{#pdf1c} Let browser PDF viewer handle scroll
182			e.preventDefault();
183			if (e.deltaY < 0) {
184				zoomIn(e.clientX, e.clientY);
185			} else {
186				zoomOut(e.clientX, e.clientY);
187			}
188		}
189	
190		/**
191		 * #{#zom2a} #{#pdf1c} Handle mouse down to start drag-scrolling — disabled for PDFs
192		 */
193		function handleMouseDown(e: MouseEvent) {
194			if (isPdf) return; // #{#pdf1c}
195			if (zoom > MIN_ZOOM) {
196				isDragging = true;
197				dragStartX = e.clientX;
198				dragStartY = e.clientY;
199				scrollStartX = scrollContainer?.scrollLeft ?? 0;
200				scrollStartY = scrollContainer?.scrollTop ?? 0;
201				e.preventDefault();
202			}
203		}
204	
205		/**
206		 * #{#zom2a} Handle mouse move for drag-scrolling
207		 */
208		function handleMouseMove(e: MouseEvent) {
209			if (isDragging && scrollContainer) {
210				scrollContainer.scrollLeft = scrollStartX - (e.clientX - dragStartX);
211				scrollContainer.scrollTop = scrollStartY - (e.clientY - dragStartY);
212			}
213		}
214	
215		/**
216		 * #{#zom2a} Handle mouse up to stop drag-scrolling
217		 */
218		function handleMouseUp() {
219			isDragging = false;
220		}
221	
222		/**
223		 * #{#zom2b} #{#zom5a} #{#pdf1c} Handle keyboard navigation — zoom/pan disabled for PDFs
224		 */
225		function handleKeydown(e: KeyboardEvent) {
226			// Only handle keyboard shortcuts when the image viewer is open
227			if (!show) return;
228	
229			// Escape key closes modal - #{#zom5a} — works for both images and PDFs
230			if (e.key === 'Escape') {
231				close();
232				return;
233			}
234	
235			// #{#pdf1c} Skip zoom/pan keyboard shortcuts for PDFs
236			if (isPdf) return;
237	
238			// Arrow keys for scrolling when zoomed - #{#zom2b}
239			if (zoom > MIN_ZOOM && scrollContainer) {
240				switch (e.key) {
241					case 'ArrowUp':
242						scrollContainer.scrollTop -= PAN_STEP;
243						e.preventDefault();
244						break;
245					case 'ArrowDown':
246						scrollContainer.scrollTop += PAN_STEP;
247						e.preventDefault();
248						break;
249					case 'ArrowLeft':
250						scrollContainer.scrollLeft -= PAN_STEP;
251						e.preventDefault();
252						break;
253					case 'ArrowRight':
254						scrollContainer.scrollLeft += PAN_STEP;
255						e.preventDefault();
256						break;
257				}
258			}
259	
260			// Optional keyboard shortcuts for zoom - #{#zom2b}
261			if (e.key === '+' || e.key === '=') {
262				zoomIn();
263				e.preventDefault();
264			} else if (e.key === '-') {
265				zoomOut();
266				e.preventDefault();
267			} else if (e.key === '0') {
268				resetZoom();
269				e.preventDefault();
270			}
271		}
272	
273		/**
274		 * #{#zom3a} Calculate distance between two touch points
275		 */
276		function getTouchDistance(e: TouchEvent): number {
277			if (e.touches.length < 2) return 0;
278			const touch1 = e.touches[0];
279			const touch2 = e.touches[1];
280			const dx = touch1.clientX - touch2.clientX;
281			const dy = touch1.clientY - touch2.clientY;
282			return Math.sqrt(dx * dx + dy * dy);
283		}
284	
285		/**
286		 * #{#zom3a} Get midpoint between two touch points
287		 */
288		function getTouchMidpoint(e: TouchEvent): { x: number; y: number } {
289			return {
290				x: (e.touches[0].clientX + e.touches[1].clientX) / 2,
291				y: (e.touches[0].clientY + e.touches[1].clientY) / 2
292			};
293		}
294	
295		/**
296		 * #{#zom3a} #{#pdf1c} Handle touch start for pinch zoom and pan — disabled for PDFs
297		 */
298		function handleTouchStart(e: TouchEvent) {
299			if (isPdf) return; // #{#pdf1c}
300			if (e.touches.length === 2) {
301				// Pinch zoom start
302				touchStartDistance = getTouchDistance(e);
303				touchStartZoom = zoom;
304				e.preventDefault();
305			} else if (e.touches.length === 1) {
306				// Check for double tap - #{#zom3a}
307				const now = Date.now();
308				if (now - lastTapTime < DOUBLE_TAP_DELAY) {
309					// Double tap detected — zoom toward tap point
310					if (zoom === MIN_ZOOM) {
311						zoomTo(DOUBLE_TAP_ZOOM, e.touches[0].clientX, e.touches[0].clientY);
312					} else {
313						resetZoom();
314					}
315					e.preventDefault();
316				}
317				lastTapTime = now;
318	
319				// Single touch drag-scroll (if zoomed)
320				if (zoom > MIN_ZOOM) {
321					isDragging = true;
322					dragStartX = e.touches[0].clientX;
323					dragStartY = e.touches[0].clientY;
324					scrollStartX = scrollContainer?.scrollLeft ?? 0;
325					scrollStartY = scrollContainer?.scrollTop ?? 0;
326				}
327			}
328		}
329	
330		/**
331		 * #{#zom3a} #{#pdf1c} Handle touch move for pinch zoom and pan — disabled for PDFs
332		 */
333		function handleTouchMove(e: TouchEvent) {
334			if (isPdf) return; // #{#pdf1c}
335			if (e.touches.length === 2) {
336				// Pinch zoom — anchored at midpoint between fingers
337				const currentDistance = getTouchDistance(e);
338				const mid = getTouchMidpoint(e);
339				const newZoom = touchStartZoom * (currentDistance / touchStartDistance);
340				zoomTo(newZoom, mid.x, mid.y);
341				e.preventDefault();
342			} else if (e.touches.length === 1 && isDragging && scrollContainer) {
343				// Drag to scroll
344				scrollContainer.scrollLeft = scrollStartX - (e.touches[0].clientX - dragStartX);
345				scrollContainer.scrollTop = scrollStartY - (e.touches[0].clientY - dragStartY);
346				e.preventDefault();
347			}
348		}
349	
350		/**
351		 * #{#zom3a} Handle touch end
352		 */
