11	/**
12	 * What we agree to STORE — these describe the Receipt Image produced by
13	 * `prepareFileForUpload`, not the Source File a person picked.
14	 */
15	const MAX_IMAGE_MB = 5;
16	const MAX_PDF_MB = 10;
17	
18	/**
19	 * What we are willing to DECODE. Purely a memory guard: above this, loading the
20	 * image to shrink it can wedge or crash the tab, so nothing is gained by trying.
21	 * It is not a statement about acceptable receipts — a 12MB phone photo is fine.
22	 */
23	const MAX_SOURCE_MB = 25;
24	
25	type Validation = { ok: true } | { ok: false; message: string };
26	
27	/**
28	 * The Receipt Image to store, and how it came to be — recorded at the point it
29	 * is known rather than reconstructed later from a flag. `stored-as-received`
30	 * (PDFs) and `shrink-failed` are different situations that happen to produce the
31	 * same file, and only the second is worth apologizing for.
32	 */
33	type PreparedUpload = {
34		file: File;
35		outcome: 'transcoded' | 'stored-as-received' | 'shrink-failed';
36	};
37	
38	const megabytes = (file: File) => file.size / (1024 * 1024);
