50		/**
51		 * Call the server-side OCR API to extract receipt data
52		 */
53		private async extractOcrData(fileUrl: string, mimeType: string): Promise<ReceiptExtract | null> {
54			try {
55				const response = await fetch('/api/ocr/extract', {
56					method: 'POST',
57					headers: {
58						'Content-Type': 'application/json'
59					},
60					body: JSON.stringify({ fileUrl, mimeType })
61				});
62	
63				if (!response.ok) {
64					const errorText = await response.text();
65					throw new Error(`OCR API error: ${response.status} - ${errorText}`);
66				}
67	
68				const result = await response.json();
69				return result.data;
70			} catch (e) {
71				console.error('OCR extraction failed:', e);
72				return null;
73			}
74		}
