76		async list(
77			sort: 'transaction_date' | 'merchant_name' | 'total_amount' = 'transaction_date',
78			direction: 'asc' | 'desc' = 'desc'
79		) {
80			return withRetry(async () => {
81				const user = (await this.supabase.auth.getUser()).data.user;
82				if (!user) throw new Error('Not authenticated');
83	
84				console.log('[ReceiptService] Fetching receipts for user:', user.id);
85	
86				// Check family memberships for debugging
87				const { data: familyMemberships, error: fmError } = await this.supabase
88					.from('family_members')
89					.select('*')
90					.eq('user_id', user.id);
91				console.log('[ReceiptService] Family memberships:', familyMemberships, fmError);
92	
93				// Don't filter by user_id - let RLS policies handle access based on family membership
94				// This allows family members to see each other's receipts
95				const { data, error } = await this.supabase
96					.from('receipts')
97					.select('*')
98					.order(sort, { ascending: direction === 'asc' });
99				if (error) throw error;
100	
101				console.log('[ReceiptService] Fetched receipts:', {
102					count: data.length,
103					sample: data[0]
104						? {
105								id: data[0].id,
106								merchant_name: data[0].merchant_name,
107								family_id: data[0].family_id,
108								user_id: data[0].user_id
109							}
110						: 'none'
111				});
112	
113				return data as ReceiptRow[];
114			});
115		}
