117		/** Fields that are safe to send in an update — matches ReceiptInsert keys */
118		static readonly #EDITABLE_FIELDS: ReadonlySet<string> = new Set([
119			'receipt_image_path',
120			'transaction_date',
121			'total_amount',
122			'tax',
123			'merchant_name',
124			'credit_card_name',
125			'credit_card_last_4',
126			'currency',
127			'exchange_rate_to_cad',
128			'matched_transaction_id',
129			'suspicious_date',
130			'split_group_id'
131		]);
132	
133		async update(id: string, patch: ReceiptInsert) {
134			return withRetry(async () => {
135				// Strip non-editable fields (id, user_id, created_at, etc.) to prevent
136				// Supabase 400 errors from invalid values being sent in the update.
137				const safePatch: ReceiptInsert = {};
138				const source = patch as Record<string, unknown>;
139				const target = safePatch as Record<string, unknown>;
140				for (const key of Object.keys(patch)) {
141					if (ReceiptService.#EDITABLE_FIELDS.has(key)) {
142						target[key] = source[key];
143					}
144				}
145	
146				// #{#dtv1b} #{#dtv2d} Saving a receipt through the edit modal clears the
147				// suspicious-date flag. The modal always sends transaction_date, so a save
148				// (date corrected or left as-is) is treated as the user's review/confirmation
149				// of the date — there is no separate "confirm date" action. Only OCR/automated
150				// extraction sets the flag in the first place.
151				if ('transaction_date' in safePatch) {
152					safePatch.suspicious_date = false;
153				}
154	
155				const { data, error } = await this.supabase
156					.from('receipts')
157					.update(safePatch)
158					.eq('id', id)
159					.select('*')
160					.single();
161				if (error) throw error;
162				return data as ReceiptRow;
163			});
164		}
165	
166		async createManual(
167			values: Required<Pick<ReceiptInsert, 'merchant_name' | 'total_amount' | 'transaction_date'>> &
168				Partial<ReceiptInsert>
169		) {
170			return withRetry(async () => {
171				// Manual receipts are intentional - user is explicitly entering the date
172				// Skip suspicious date validation to avoid false positives for old receipts
173				const valuesWithFlag: ReceiptInsert = {
174					...values,
175					suspicious_date: false
176				};
177	
178				const { data, error } = await this.supabase
179					.from('receipts')
180					.insert(valuesWithFlag)
181					.select('*')
182					.single();
183				if (error) throw error;
184				return data as ReceiptRow;
185			});
186		}
