188		/**
189		 * Gate the Source File before we decode it: is this a kind of file we handle,
190		 * and is it small enough to be worth loading into memory at all?
191		 *
192		 * Deliberately says nothing about the 5MB image limit — that limit describes
193		 * what we store, and this file has not been shrunk yet. See
194		 * `docs/adr/0006-the-stored-image-is-the-contract.md`.
195		 */
196		validateSourceFile(file: File): Validation {
197			if (!ACCEPTED_UPLOAD_TYPES.includes(file.type)) {
198				return { ok: false, message: 'Unsupported file type. Allowed: JPEG, PNG, HEIC, PDF.' };
199			}
200			if (megabytes(file) > MAX_SOURCE_MB) {
201				return { ok: false, message: `File too large to process. Max ${MAX_SOURCE_MB}MB.` };
202			}
203			return { ok: true };
204		}
205	
206		/**
207		 * Gate the Receipt Image we are about to store. Reached only after the resize,
208		 * so an image over the limit here means the shrink did not happen — say that,
209		 * rather than telling someone their photo is too big when the app's own job
210		 * was to make it smaller.
211		 */
212		validateReceiptImage({ file, outcome }: PreparedUpload): Validation {
213			const sizeMB = megabytes(file);
214			const limit = outcome === 'stored-as-received' ? MAX_PDF_MB : MAX_IMAGE_MB;
215			if (sizeMB <= limit) return { ok: true };
216	
217			switch (outcome) {
218				case 'stored-as-received':
219					return { ok: false, message: `PDF too large. Max ${MAX_PDF_MB}MB.` };
220				case 'shrink-failed':
221					return {
222						ok: false,
223						message: `This image could not be shrunk, and the original is over ${MAX_IMAGE_MB}MB. Try a smaller photo.`
224					};
225				case 'transcoded':
226					return { ok: false, message: `Image too large. Max ${MAX_IMAGE_MB}MB.` };
227			}
228		}
229	
230		/**
231		 * Upload a receipt file, extract its data via OCR, and persist the receipt row.
232		 *
233		 * Resilience invariants (see upload-pipeline-resilience spec):
234		 * - OCR is best-effort: any OCR failure still creates the receipt without extracted data.
235		 * - No orphan storage files: if the insert fails after upload, the blob is removed.
236		 */
237		async uploadAndCreate(file: File) {
238			const source = this.validateSourceFile(file);
239			if (!source.ok) throw new Error(source.message);
240	
241			// Shrink first, then judge the result. Both steps sit outside withRetry:
242			// a rejection here is deterministic, so retrying it would only delay the
243			// error, and re-decoding the image on every attempt wastes memory.
244			const prepared = await this.prepareFileForUpload(file);
245			const artifact = this.validateReceiptImage(prepared);
246			if (!artifact.ok) throw new Error(artifact.message);
247	
248			// #{#ofn2a} The name the person recognizes is the only thing we still need
249			// from the Source File. Reading it here rather than inside the retry lets
250			// the original — up to MAX_SOURCE_MB of it — be collected immediately,
251			// instead of being pinned by the closure for the whole upload.
252			const originalFilename = sanitizeFilename(file.name);
253	
254			return withRetry(async () => {
255				const path = await this.uploadToStorage(prepared.file);
256				const extract = await this.extractReceiptDataFailSoft(path, prepared.file.type);
257				const values = await this.buildReceiptInsert(originalFilename, path, extract);
258				const data = await this.insertReceiptOrCleanupUpload(values, path);
259				await this.autoAssignCategoryBestEffort(data, extract?.merchant_name ?? null);
260				return data as ReceiptRow;
261			});
262		}
263	
264		/**
265		 * #{#rsz2a} Turn the Source File into the Receipt Image: every image becomes a
266		 * JPEG within the pixel budget. PDFs pass through untouched.
267		 *
268		 * A failure is not fatal here — the original is returned, and the outcome lets
269		 * the caller explain the eventual rejection accurately.
270		 */
271		private async prepareFileForUpload(file: File): Promise<PreparedUpload> {
272			if (!isResizableImage(file.type)) return { file, outcome: 'stored-as-received' };
273	
274			try {
275				const resized = await resizeImage(file);
276				console.log(
277					`Image resized: ${(file.size / 1024).toFixed(2)}KB → ${(resized.size / 1024).toFixed(2)}KB (${((1 - resized.size / file.size) * 100).toFixed(1)}% reduction)`
278				);
279				return { file: resized, outcome: 'transcoded' };
280			} catch (error) {
281				console.error('Image resize failed, using original:', error);
282				return { file, outcome: 'shrink-failed' };
283			}
284		}
