286		/** Upload the file under the user's folder and return its storage path. Throws on failure. */
287		private async uploadToStorage(fileToUpload: File): Promise<string> {
288			const user = (await this.supabase.auth.getUser()).data.user;
289			if (!user) throw new Error('Not authenticated');
290			const folder = `${user.id}`;
291			const fileExt = fileToUpload.name.split('.').pop()?.toLowerCase() ?? 'bin';
292			const path = `${folder}/${crypto.randomUUID()}.${fileExt}`;
293			const { error: upErr } = await this.supabase.storage
294				.from('receipts')
295				.upload(path, fileToUpload, {
296					contentType: fileToUpload.type,
297					upsert: false
298				});
299			if (upErr) throw upErr;
300			return path;
301		}
