303		/**
304		 * #{#sec2a} OCR via a short-lived signed URL. Best-effort: returns null when the signed
305		 * URL cannot be generated or the OCR API fails, so the upload pipeline survives outages.
306		 */
307		private async extractReceiptDataFailSoft(
308			path: string,
309			mimeType: string
310		): Promise<ReceiptExtract | null> {
311			const signedUrl = await getSignedReceiptUrl(path, 300);
312			return signedUrl ? await this.extractOcrData(signedUrl, mimeType) : null;
313		}
