315		/** #{#fcr1a} #{#fcr2a} Fetch exchange rate at scan time for foreign currency receipts. */
316		private async fetchExchangeRateBestEffort(
317			currency: string | null,
318			transactionDate: string | null
319		): Promise<number | null> {
320			if (!currency || currency === 'CAD' || !transactionDate) return null;
321			try {
322				const { ExchangeRateService } = await import('./ExchangeRateService');
323				return await ExchangeRateService.fetchRate(currency, transactionDate);
324			} catch {
325				// Rate fetch is best-effort — receipt is saved without rate
326				return null;
327			}
328		}
