486		 *
487		 * Creates a new receipt with the specified split amount and reduces the
488		 * original receipt's amount accordingly. Both receipts share a split_group_id.
489		 *
490		 * @param receiptId The ID of the receipt to split
491		 * @param splitAmount The amount for the new split receipt
492		 * @returns The new receipt and the updated original
493		 */
494		async splitReceipt(
495			receiptId: string,
496			splitAmount: number,
497			splitDate?: string | null
498		): Promise<{ newReceipt: ReceiptRow; updatedOriginal: ReceiptRow }> {
499			// Validate inputs before any DB calls
500			ReceiptService.validateSplitAmount(splitAmount);
501			ReceiptService.validateSplitDate(splitDate);
502	
503			return withRetry(async () => {
504				// Auth check
505				const user = (await this.supabase.auth.getUser()).data.user;
506				if (!user) throw new Error('Not authenticated');
507	
508				const original = await this.fetchOriginalForSplit(receiptId);
509				const remainingAmount = ReceiptService.validateAndComputeRemaining(
510					original.total_amount,
511					splitAmount
512				);
513	
514				// #{#spl1b} - Determine split_group_id
515				const splitGroupId = original.split_group_id ?? crypto.randomUUID();
516	
517				// #{#spl5a} - Insert new receipt first, then update original
518				const newReceipt = await this.insertSplitReceipt(
519					ReceiptService.buildSplitReceiptInsert(original, splitAmount, splitDate, splitGroupId)
520				);
521				const updatedOriginal = await this.reduceOriginalAfterSplitOrRollback(
522					receiptId,
523					remainingAmount,
524					splitGroupId,
525					newReceipt.id
526				);
527	
528				return { newReceipt, updatedOriginal };
529			});
530		}
