532		/** #{#spl2b} Reject non-finite, non-positive, or sub-cent split amounts. */
533		private static validateSplitAmount(splitAmount: number): void {
534			if (!Number.isFinite(splitAmount) || splitAmount <= 0) {
535				throw new Error('Split amount must be a positive finite number');
536			}
537			// Check at most 2 decimal places
538			if (Math.round(splitAmount * 100) !== splitAmount * 100) {
539				throw new Error('Split amount can have at most 2 decimal places');
540			}
541		}
542	
543		/** #{#spl7c} Reject malformed or impossible (e.g. 2026-02-30) split dates when provided. */
544		private static validateSplitDate(splitDate?: string | null): void {
545			if (splitDate === undefined || splitDate === null) return;
546	
547			if (splitDate === '' || !/^\d{4}-\d{2}-\d{2}$/.test(splitDate)) {
548				throw new Error('Please enter a valid date');
549			}
550			const parsed = new Date(splitDate);
551			if (isNaN(parsed.getTime())) {
552				throw new Error('Please enter a valid date');
553			}
554			// Verify the date components match (catches 2026-02-30 etc.)
555			const [year, month, day] = splitDate.split('-').map(Number);
556			if (
557				parsed.getUTCFullYear() !== year ||
558				parsed.getUTCMonth() !== month - 1 ||
559				parsed.getUTCDate() !== day
560			) {
561				throw new Error('Please enter a valid date');
562			}
563		}
564	
565		private async fetchOriginalForSplit(receiptId: string): Promise<ReceiptRow> {
566			const { data: original, error: fetchError } = await this.supabase
567				.from('receipts')
568				.select('*')
569				.eq('id', receiptId)
570				.single();
571			if (fetchError) throw fetchError;
572			if (!original) throw new Error('Receipt not found');
573			return original as ReceiptRow;
574		}
575	
576		/**
577		 * Third split-validation step (after `validateSplitAmount` / `validateSplitDate`):
578		 * the total-relative rule. Unlike the other two it runs post-fetch because it needs
579		 * the original's total, and it returns the remainder it computes to validate — the
580		 * name says so rather than reading as a pure compute. Throws when the receipt has no
581		 * amount, or when the split isn't strictly less than the total (no positive remainder).
582		 */
583		private static validateAndComputeRemaining(
584			originalAmount: number | null,
585			splitAmount: number
586		): number {
587			if (originalAmount == null || originalAmount <= 0) {
588				throw new Error('Cannot split a receipt with no amount');
589			}
590			const remainingAmount = Math.round((originalAmount - splitAmount) * 100) / 100;
591			if (splitAmount >= originalAmount || remainingAmount <= 0) {
592				throw new Error('Split amount must be less than the receipt total');
593			}
594			return remainingAmount;
595		}
596	
597		/** The new split inherits the original's identity fields but never its transaction match. */
598		private static buildSplitReceiptInsert(
599			original: ReceiptRow,
600			splitAmount: number,
601			splitDate: string | null | undefined,
602			splitGroupId: string
603		): ReceiptInsert {
604			// #{#spl7a} - Use splitDate if provided, otherwise inherit from original
605			const effectiveDate = splitDate ?? original.transaction_date;
606	
607			// #{#spl7a} #{#spl7c} - Recalculate suspicious_date based on the split's own date
608			const effectiveSuspicious = splitDate ? isSuspiciousDate(splitDate) : original.suspicious_date;
609	
610			return {
611				receipt_image_path: original.receipt_image_path,
612				transaction_date: effectiveDate,
613				total_amount: splitAmount,
614				tax: null,
615				merchant_name: original.merchant_name,
616				credit_card_name: original.credit_card_name,
617				credit_card_last_4: original.credit_card_last_4,
618				currency: original.currency,
619				matched_transaction_id: null,
620				suspicious_date: effectiveSuspicious,
621				split_group_id: splitGroupId
622			};
623		}
624	
625		private async insertSplitReceipt(newReceiptData: ReceiptInsert): Promise<ReceiptRow> {
626			const { data: newReceipt, error: insertError } = await this.supabase
627				.from('receipts')
628				.insert(newReceiptData)
629				.select('*')
630				.single();
631			if (insertError) throw insertError;
632			return newReceipt as ReceiptRow;
633		}
634	
635		/**
636		 * #{#spl5a} Update the original (reduce amount, set split_group_id, clear match).
637		 * On failure, best-effort delete of the just-inserted split keeps the pair consistent.
638		 */
639		private async reduceOriginalAfterSplitOrRollback(
640			receiptId: string,
641			remainingAmount: number,
642			splitGroupId: string,
643			newReceiptId: string
644		): Promise<ReceiptRow> {
645			const { data: updatedOriginal, error: updateError } = await this.supabase
646				.from('receipts')
647				.update({
648					total_amount: remainingAmount,
649					matched_transaction_id: null,
650					split_group_id: splitGroupId
651				})
652				.eq('id', receiptId)
653				.select('*')
654				.single();
655	
656			if (updateError) {
657				// Rollback: delete the newly created receipt
658				try {
659					await this.supabase.from('receipts').delete().eq('id', newReceiptId);
660				} catch {
661					// Best-effort rollback
662				}
663				throw updateError;
664			}
665	
666			return updatedOriginal as ReceiptRow;
667		}
668	
669		/**
670		 * #{#blk3a} Bulk delete multiple receipts in a single database operation
671		 * @param receiptIds Array of receipt IDs to delete
672		 * @returns Promise that resolves when deletion is complete
673		 */
674		async bulkDeleteReceipts(receiptIds: string[]): Promise<{ deletedCount: number }> {
675			return withRetry(async () => {
676				// Get authenticated user
677				const user = (await this.supabase.auth.getUser()).data.user;
678				if (!user) throw new Error('Not authenticated');
679	
680				// Delete all receipts in a single query using IN clause
681				// Only delete receipts belonging to the authenticated user
682				const { error } = await this.supabase
683					.from('receipts')
684					.delete()
685					.in('id', receiptIds)
686					.eq('user_id', user.id);
687	
688				if (error) throw error;
689	
690				// Return metadata about deletion
691				return { deletedCount: receiptIds.length };
692			});
693		}
694	}
